  "retro.q.teamwork.hint": { en: "How well did the alliances work together?", de: "Wie gut haben die Allianzen zusammengearbeitet?", ko: "연맹들이 얼마나 잘 협력했나요?", pl: "Jak dobrze sojusze ze sobą współpracowały?", ar: "ما مدى جودة تعاون التحالفات معًا؟" },

