  "retro.t.suggestions": { en: "Suggestions for next time", de: "Vorschläge für das nächste Mal", ko: "다음을 위한 제안", pl: "Sugestie na następny raz", ar: "اقتراحات للمرة القادمة" },
  "retro.t.suggestions.hint": { en: "Ideas big or small are welcome.", de: "Ideen, groß oder klein, sind willkommen.", ko: "크든 작든 어떤 아이디어도 환영합니다.", pl: "Pomysły, duże i małe, są mile widziane.", ar: "الأفكار، كبيرة كانت أو صغيرة، مرحّب بها." },

